/**
 * boing.network golden signing vectors (docs/fixtures/tx-signing-golden-vectors.json, generated by the Rust test
 * crates/boing-primitives/tests/tx_signing_golden.rs). The wallet must reproduce, byte for byte:
 * payload + access-list bincode, the signing preimage and digest (BOING_TX_V2 untipped, BOING_TX_PRIORITY tipped),
 * the deterministic Ed25519 signature and the full SignedTransaction wire bytes.
 *
 * The file is vendored in tests/fixtures; refresh it with `pnpm fixtures:sync` (never hand-edit).
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import * as ed from '@noble/ed25519';
import { blake3 } from '@noble/hashes/blake3.js';
import { encodeAccessList, encodePayload, encodeSignedTransaction } from '../src/boing/bincode';
import { signableHashV2, signableHashWithTip, signTransaction } from '../src/boing/signing';
import type { AccessList, Payload, Transaction } from '../src/boing/types';

interface Vector {
  name: string;
  chain_id: number;
  nonce: string;
  sender: string;
  domain: 'BOING_TX_V2' | 'BOING_TX_PRIORITY';
  priority_tip: string;
  payload: { kind: string; to?: string; amount?: string; contract?: string; calldata?: string };
  access_list: { read: string[]; write: string[] };
  payload_bincode_hex: string;
  access_list_bincode_hex: string;
  preimage_hex: string;
  signing_digest_hex: string;
  signature_hex: string;
  signed_tx_bincode_hex: string;
}
interface Fixture {
  signer_public_key_hex: string;
  signer_seed_hex: string;
  vectors: Vector[];
}

const fixture = JSON.parse(readFileSync(new URL('./fixtures/tx-signing-golden-vectors.json', import.meta.url), 'utf8')) as Fixture;

const fromHex = (h: string): Uint8Array => {
  const s = h.replace(/^0x/i, '');
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16);
  return out;
};
const hex = (b: Uint8Array) => Array.from(b).map((x) => x.toString(16).padStart(2, '0')).join('');

function payloadOf(v: Vector): Payload {
  const p = v.payload;
  if (p.kind === 'transfer') return { kind: 'transfer', to: fromHex(p.to!), amount: BigInt(p.amount!) };
  if (p.kind === 'contractCall') return { kind: 'contract_call', contract: fromHex(p.contract!), calldata: fromHex(p.calldata!) };
  throw new Error(`fixture has a payload kind this test does not know: ${p.kind} (extend payloadOf)`);
}

function txOf(v: Vector): Transaction {
  const access_list: AccessList = { read: v.access_list.read.map(fromHex), write: v.access_list.write.map(fromHex) };
  const tip = BigInt(v.priority_tip);
  return { nonce: BigInt(v.nonce), sender: fromHex(v.sender), payload: payloadOf(v), access_list, ...(tip > 0n ? { priorityTip: tip } : {}) } as Transaction;
}

const seed = fromHex(fixture.signer_seed_hex);

describe('boing.network golden signing vectors', () => {
  it('fixture is present and covers v2, tipped, mainnet and u128-max tip', () => {
    const names = fixture.vectors.map((v) => v.name);
    expect(fixture.vectors.length).toBeGreaterThanOrEqual(5);
    expect(fixture.vectors.some((v) => v.domain === 'BOING_TX_V2' && v.priority_tip === '0')).toBe(true);
    expect(fixture.vectors.some((v) => v.domain === 'BOING_TX_PRIORITY')).toBe(true);
    expect(fixture.vectors.some((v) => v.chain_id === 6914)).toBe(true);
    expect(fixture.vectors.some((v) => v.priority_tip === ((1n << 128n) - 1n).toString())).toBe(true);
    expect(new Set(names).size).toBe(names.length);
  });

  it('the documented signer seed derives the documented public key', async () => {
    expect(hex(await ed.getPublicKeyAsync(seed))).toBe(fixture.signer_public_key_hex);
  });

  describe.each(fixture.vectors.map((v) => [v.name, v] as const))('%s', (_name, v) => {
    const tx = txOf(v);
    const chain = BigInt(v.chain_id);
    const tipped = BigInt(v.priority_tip) > 0n;

    it('domain follows the tip: V2 when zero, BOING_TX_PRIORITY otherwise', () => {
      expect(v.domain).toBe(tipped ? 'BOING_TX_PRIORITY' : 'BOING_TX_V2');
      const domainBytes = new TextEncoder().encode(v.domain);
      expect(hex(fromHex(v.preimage_hex).subarray(0, domainBytes.length))).toBe(hex(domainBytes));
    });

    it('payload and access-list bincode match', () => {
      expect(hex(encodePayload(tx.payload))).toBe(v.payload_bincode_hex);
      expect(hex(encodeAccessList(tx.access_list))).toBe(v.access_list_bincode_hex);
    });

    it('digest equals the documented BLAKE3 of the preimage, and the wallet reproduces it', () => {
      expect(hex(blake3(fromHex(v.preimage_hex)))).toBe(v.signing_digest_hex);
      const mine = tipped ? signableHashWithTip(tx, chain) : signableHashV2(tx, chain);
      expect(hex(mine)).toBe(v.signing_digest_hex);
      // signableHashWithTip with a zero tip must collapse to the untipped v2 digest.
      expect(hex(signableHashWithTip(tx, chain, 0n))).toBe(hex(signableHashV2(tx, chain)));
    });

    it('signature (deterministic Ed25519) and SignedTransaction wire bytes match', async () => {
      const sig = await signTransaction(tx, seed, chain);
      expect(hex(sig)).toBe(v.signature_hex);
      expect(hex(encodeSignedTransaction({ tx, signature: sig }))).toBe(v.signed_tx_bincode_hex);
    });
  });

  it('chain id is bound: the same tipped tx has different digests on 6913 and 6914', () => {
    const t = fixture.vectors.find((v) => v.name === 'transfer_tip_1_testnet')!;
    const m = fixture.vectors.find((v) => v.name === 'transfer_tip_1_mainnet_differs_from_testnet')!;
    expect(t.signing_digest_hex).not.toBe(m.signing_digest_hex);
  });
});